('av_QwJX3ZFvXfOPepNlWB5MskldauwhyP140dIYZeW5MnCR_s1oIO6vI--5mbGEjKzdAdOEVbES8hyC34I','义父们送我上大学4',2026,'short_drama','中国大陆','国语','["AI漫剧","现代都市","短剧"]','["蔡一智","陈炜","陈晓华","陈滢","高海宁","黄子恒","姜大卫","蒋家旻","蒋祖曼","孔德贤","倪嘉雯","吴卓羲"]','["陈维冠"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/4f/4fe8ce4c5150f69dfc46c8d81518080fb6bcb359a232811c5ad0e5411d31f04f.webp',NULL,'失联两年后,老吴以宋家继承人宋书年的身份回到义父小馆,揭开当年被亲母逼回宋家的真相。家人心疼又气恼,重新接纳并守护他,他也暗中扶持潘子、收购恒远,学会用力量保护家人。与此同时,夏夏入职狼性公司,在陆景川的严苛考验中不断碰壁,逐渐明白职场规则与自我底线。小馆的温暖让两人走出伤痛,重新选择未来。','全1集',1,1,70.72,'2026-09-13T12:47:16.849Z'),
